56     //   }}}
57 
58     //   Pipeline stage 1
59     //   {{{
60     input  logic                   st1_req_valid_i,
61     input  logic                   st1_req_abort_i,
62     input  logic                   st1_req_rtab_i,
63     input  logic                   st1_req_is_error_i,
64     input  logic                   st1_req_is_uncacheable_i,
65     input  logic                   st1_req_need_rsp_i,
66     input  logic                   st1_req_is_load_i,
67     input  logic                   st1_req_is_store_i,
68     input  logic                   st1_req_is_amo_i,
69     input  logic                   st1_req_is_cmo_inval_i,
70     input  logic                   st1_req_is_cmo_flush_i,
71     input  logic                   st1_req_is_cmo_fence_i,
72     input  logic                   st1_req_is_cmo_prefetch_i,
73     input  logic                   st1_req_wr_wt_i,
74     input  logic                   st1_req_wr_wb_i,
75     input  logic                   st1_req_wr_auto_i,
