85     output logic                   st1_rsp_valid_o,
86     output logic                   st1_rsp_error_o,
87     output logic                   st1_rsp_aborted_o,
88     output logic                   st1_req_cachedir_sel_victim_o,
89     output logic                   st1_req_cachedir_updt_sel_victim_o,
90     output logic                   st1_req_cachedata_write_o,
91     output logic                   st1_req_cachedata_write_enable_o,
92     input  logic                   st1_mshr_alloc_ready_i,
93     input  logic                   st1_mshr_hit_i,
94     input  logic                   st1_mshr_full_i,
95     //   }}}
96 
97     //   Pipeline stage 2
98     //   {{{
99     input  logic                   st2_mshr_alloc_i,
100     input  logic                   st2_mshr_alloc_is_prefetch_i,
101     input  logic                   st2_mshr_alloc_wback_i,
102     output logic                   st2_mshr_alloc_o,
103     output logic                   st2_mshr_alloc_cs_o,
104     output logic                   st2_mshr_alloc_need_rsp_o,
105     output logic                   st2_mshr_alloc_wback_o,
106 
107     input  logic                   st2_dir_updt_i,
108     input  logic                   st2_dir_updt_valid_i,
109     input  logic                   st2_dir_updt_wback_i,
110     input  logic                   st2_dir_updt_dirty_i,
111     input  logic                   st2_dir_updt_fetch_i,
112     output logic                   st2_dir_updt_o,
113     output logic                   st2_dir_updt_valid_o,
114     output logic                   st2_dir_updt_wback_o,
115     output logic                   st2_dir_updt_dirty_o,
116     output logic                   st2_dir_updt_fetch_o,
117     //   }}}
118 
119     //   Replay
120     //   {{{
121     input  logic                   rtab_full_i,
122     input  logic                   rtab_fence_i,
123     output logic                   rtab_check_o,
124     input  logic                   rtab_check_hit_i,
125     output logic                   st1_rtab_alloc_o,
126     output logic                   st1_rtab_alloc_and_link_o,
127     output logic                   st1_rtab_commit_o,
128     output logic                   st1_rtab_rback_o,
129     output logic                   st1_rtab_mshr_hit_o,
130     output logic                   st1_rtab_mshr_full_o,
131     output logic                   st1_rtab_mshr_ready_o,
132     output logic                   st1_rtab_write_miss_o,
133     output logic                   st1_rtab_wbuf_hit_o,
134     output logic                   st1_rtab_wbuf_not_ready_o,
135     output logic                   st1_rtab_dir_unavailable_o,
136     output logic                   st1_rtab_dir_fetch_o,
137     output logic                   st1_rtab_flush_hit_o,
138     output logic                   st1_rtab_flush_not_ready_o,
139     //   }}}
140 
141     //   Cache directory
142     //   {{{
143     input  logic                   cachedir_hit_i,
144     input  logic                   cachedir_init_ready_i,
145     //   }}}
146 
147     //   Refill interface
148     //   {{{
149     input  logic                   refill_busy_i,
150     input  logic                   refill_core_rsp_valid_i,
151     //   }}}
152 
153     //   Write buffer
154     //   {{{
155     input  logic                   wbuf_write_ready_i,
156     input  logic                   wbuf_read_hit_i,
157     output logic                   wbuf_write_valid_o,
158     output logic                   wbuf_write_uncacheable_o,
159     output logic                   wbuf_read_flush_hit_o,
160     //   }}}
161 
162     //   Flush controller
163     input  logic                   flush_busy_i,
164     input  logic                   st1_flush_check_hit_i,
165     input  logic                   st1_flush_alloc_ready_i,
166     input  logic                   st2_flush_alloc_i,
167     output logic                   st2_flush_alloc_o,
168 
169     //   Uncacheable request handler
170     //   {{{
171     input  logic                   uc_busy_i,
172     output logic                   uc_req_valid_o,
173     output logic                   uc_core_rsp_ready_o,
174     //   }}}
175 
176     //   Cache Management Operation (CMO)
177     //   {{{
178     input  logic                   cmo_busy_i,
179     input  logic                   cmo_wait_i,
180     output logic                   cmo_req_valid_o,
181     //   }}}
182 
183     //   Configuration
184     //   {{{
185     input  logic                   cfg_default_wb_i,
186     //   }}}
187 
188     //   Performance events
189     //   {{{
190     output logic                   evt_cache_write_miss_o,
191     output logic                   evt_cache_read_miss_o,
192     output logic                   evt_uncached_req_o,
193     output logic                   evt_cmo_req_o,
194     output logic                   evt_write_req_o,
195     output logic                   evt_read_req_o,
196     output logic                   evt_prefetch_req_o,
197     output logic                   evt_req_on_hold_o,
198     output logic                   evt_rtab_rollback_o,
199     output logic                   evt_stall_refill_o,
200     output logic                   evt_stall_o
201     //   }}}
202 );
203     // }}}
204 
205     //  Definition of internal signals
206     //  {{{
207     logic  st1_fence;
208     logic  st1_rtab_alloc, st1_rtab_alloc_and_link;
209     //  }}}
210 
211     //  Global control signals
212     //  {{{
213 
214     //  Determine if the new request is a "fence". Here, fence instructions are
215     //  considered those that need to be executed in program order
216     //  (irrespectively of addresses). This means that all memory operations
217     //  arrived before the "fence" instruction need to be finished, and only
218     //  then the "fence" instruction is executed. In the same manner, all
219     //  instructions following the "fence" need to wait the completion of this
220     //  last before being executed.
221     assign st1_fence = st1_req_is_uncacheable_i |
222                        st1_req_is_cmo_fence_i   |
223                        st1_req_is_cmo_inval_i   |
224                        st1_req_is_cmo_flush_i;
225 
226     //      Trigger an event signal when a new request cannot consumed
227     assign evt_stall_o = core_req_valid_i & ~core_req_ready_o;
228     //  }}}
229 
230     //  Arbitration of responses to the core
231     //  {{{
232     assign uc_core_rsp_ready_o = ~refill_core_rsp_valid_i;
233     //  }}}
234 
235     //  Replay logic
236     //  {{{
237     //      Replay table allocation
238     assign st1_rtab_alloc_o          = st1_rtab_alloc          & ~st1_req_rtab_i,
239            st1_rtab_alloc_and_link_o = st1_rtab_alloc_and_link,
240            st1_rtab_rback_o          = st1_rtab_alloc          &  st1_req_rtab_i;
241 
242     //      Performance event
243     assign evt_req_on_hold_o   = st1_rtab_alloc | st1_rtab_alloc_and_link,
244            evt_rtab_rollback_o = st1_rtab_rback_o;
245     //  }}}
246 
247     //  Data-cache control lines
248     //  {{{
249     always_comb
250     begin : hpdcache_ctrl_comb
251         automatic logic nop;
252         automatic logic st1_nop; //  Do not consume a request in stage 0 because of stage 1 hazard
253         automatic logic st2_nop; //  Do not consume a request in stage 0 because of stage 2 haward
254         automatic logic st1_req_is_cacheable_store;
255 
256 
257         uc_req_valid_o                      = 1'b0;
258 
259         cmo_req_valid_o                     = 1'b0;
260 
261         wbuf_write_valid_o                  = 1'b0;
262         wbuf_read_flush_hit_o               = 1'b0;
263         wbuf_write_uncacheable_o            = 1'b0; // unused
264 
265         core_req_ready_o                    = 1'b0;
266         rtab_req_ready_o                    = 1'b0;
267         refill_req_ready_o                  = 1'b0;
268 
269         st0_req_mshr_check_o                = 1'b0;
270         st0_req_cachedir_read_o             = 1'b0;
271         st0_req_cachedata_read_o            = 1'b0;
272 
273         st1_req_valid_o                     = st1_req_valid_i;
274         st1_req_is_error_o                  = st1_req_is_error_i;
275         st1_req_is_cacheable_store          = 1'b0;
276         st1_nop                             = 1'b0;
277         st1_req_cachedata_write_o           = 1'b0;
278         st1_req_cachedata_write_enable_o    = 1'b0;
279         st1_req_cachedir_sel_victim_o       = 1'b0;
280         st1_req_cachedir_updt_sel_victim_o  = 1'b0;
281         st1_rsp_valid_o                     = 1'b0;
282         st1_rsp_error_o                     = 1'b0;
283         st1_rsp_aborted_o                   = 1'b0;
284 
285         st2_mshr_alloc_o                    = st2_mshr_alloc_i;
286         st2_mshr_alloc_cs_o                 = 1'b0;
287         st2_mshr_alloc_need_rsp_o           = 1'b0;
288         st2_mshr_alloc_wback_o              = st2_mshr_alloc_wback_i;
289 
290         st2_flush_alloc_o                   = st2_flush_alloc_i;
291 
292         st2_dir_updt_o                      = st2_dir_updt_i;
293         st2_dir_updt_valid_o                = st2_dir_updt_valid_i;
294         st2_dir_updt_wback_o                = st2_dir_updt_wback_i;
295         st2_dir_updt_dirty_o                = st2_dir_updt_dirty_i;
296         st2_dir_updt_fetch_o                = st2_dir_updt_fetch_i;
297 
298         st2_nop                             = 1'b0;
299 
300         nop                                 = 1'b0;
301 
302         rtab_check_o                        = 1'b0;
303         st1_rtab_alloc                      = 1'b0;
304         st1_rtab_alloc_and_link             = 1'b0;
305         st1_rtab_commit_o                   = 1'b0;
306         st1_rtab_mshr_hit_o                 = 1'b0;
307         st1_rtab_mshr_full_o                = 1'b0;
308         st1_rtab_mshr_ready_o               = 1'b0;
309         st1_rtab_write_miss_o               = 1'b0;
310         st1_rtab_wbuf_hit_o                 = 1'b0;
311         st1_rtab_wbuf_not_ready_o           = 1'b0;
312         st1_rtab_dir_unavailable_o          = 1'b0;
313         st1_rtab_dir_fetch_o                = 1'b0;
314         st1_rtab_flush_hit_o                = 1'b0;
315         st1_rtab_flush_not_ready_o          = 1'b0;
316 
317         evt_cache_write_miss_o              = 1'b0;
318         evt_cache_read_miss_o               = 1'b0;
319         evt_uncached_req_o                  = 1'b0;
320         evt_cmo_req_o                       = 1'b0;
321         evt_write_req_o                     = 1'b0;
322         evt_read_req_o                      = 1'b0;
323         evt_prefetch_req_o                  = 1'b0;
324         evt_stall_refill_o                  = 1'b0;
325 
326         //  Wait for the cache to be initialized
327         //  {{{
328         if (!cachedir_init_ready_i) begin
329             //  initialization of the cache RAMs
330         end
331         //  }}}
332 
333         //  Refilling the cache
334         //  {{{
335         else if (refill_busy_i) begin
336             //  miss handler has the control of the cache pipeline
337             evt_stall_refill_o = core_req_valid_i;
338         end
339         //  }}}
340 
341         //  Flush controller reading the cache
342         //  {{{
343         else if (flush_busy_i) begin
344             //  flush controller has the control of the cache pipeline
345         end
346         //  }}}
347 
348         //  Normal pipeline operation
349         //  {{{
350         else begin
351             //  Stage 2 request pending
352             //  {{{
353             //  Allocate an entry in the MSHR
354             if (st2_mshr_alloc_i) begin
355                 //  Reset mshr alloc request
356                 st2_mshr_alloc_o = 1'b0;
357 
358                 //  Enable the MSHR
359                 st2_mshr_alloc_cs_o = 1'b1;
360 
361                 //  Introduce a NOP in the next cycle to prevent a hazard on the MSHR
362                 st2_nop = 1'b1;
363 
364                 //  Performance event
365                 evt_cache_read_miss_o = ~st2_mshr_alloc_is_prefetch_i;
366                 evt_read_req_o        = ~st2_mshr_alloc_is_prefetch_i;
367                 evt_prefetch_req_o    =  st2_mshr_alloc_is_prefetch_i;
368             end
369 
370             //  Flush a cacheline
371             if (st2_flush_alloc_i) begin
372                 //  Reset cache directory update request
373                 st2_flush_alloc_o = 1'b0;
374 
375                 //  Introduce a NOP in the next cycle to prevent a hazard on the cache data
376                 st2_nop = 1'b1;
377             end
378 
379             //  Update the cache directory
380             if (st2_dir_updt_i) begin
381                 //  Reset cache directory update request
382                 st2_dir_updt_o = 1'b0;
383 
384                 //  Introduce a NOP in the next cycle to prevent a hazard on the cache dir
385                 st2_nop = 1'b1;
386             end
387             //  }}}
388 
389             //  Stage 1 request pending
390             //  {{{
391             if (st1_req_valid_i) begin
392                 //  Check if the request in stage 1 has a conflict with one of the
393                 //  request in the replay table.
394                 rtab_check_o = ~st1_req_rtab_i & ~st1_fence;
395 
396                 //  Check if the current request is aborted. If so, respond to the
397                 //  core (when need_rsp is set) and set the aborted flag
398                 if (st1_req_abort_i && !st1_req_rtab_i) begin
399                     st1_rsp_valid_o = st1_req_need_rsp_i;
400                     st1_rsp_aborted_o = 1'b1;
401                 end
402 
403                 else if (st1_req_is_error_i) begin
404                     st1_rtab_commit_o = st1_req_rtab_i;
405                     st1_rsp_valid_o = st1_req_need_rsp_i;
406                     st1_rsp_error_o = st1_req_need_rsp_i;
407                 end
408 
409                 //  Allocate a new entry in the replay table in case of conflict with
410                 //  an on-hold request
411                 else if (rtab_check_o && rtab_check_hit_i) begin
412                     st1_rtab_alloc_and_link = 1'b1;
413 
414                     st1_nop = 1'b1;
415                 end
416 
417                 //  CMO fence or invalidate
418                 //  {{{
419                 else if (st1_req_is_cmo_inval_i ||
420                          st1_req_is_cmo_flush_i ||
421                          st1_req_is_cmo_fence_i)
422                 begin
423                     cmo_req_valid_o = 1'b1;
424                     st1_nop         = 1'b1;
425 
426                     //  Performance event
427                     evt_cmo_req_o = 1'b1;
428                 end
429                 //  }}}
430 
431                 //  Uncacheable load, store or AMO request
432                 //  {{{
433                 else if (st1_req_is_uncacheable_i) begin
434                     uc_req_valid_o = 1'b1;
435                     st1_nop        = 1'b1;
436 
437                     //  Performance event
438                     evt_uncached_req_o = 1'b1;
439                 end
440                 //  }}}
441 
442                 //  Cacheable request
443                 //  {{{
444                 else begin
445                     //  AMO cacheable request
446                     //  {{{
447                     if (st1_req_is_amo_i) begin
448                         //  Flush required but the controller is not ready
449                         if (cachedir_hit_i && st1_dir_hit_dirty_i && !st1_flush_alloc_ready_i)
450                         begin
451                             st1_rtab_alloc = 1'b1;
452                             st1_rtab_flush_not_ready_o = 1'b1;
453                             st1_nop = 1'b1;
454                         end
455 
456                         //  Process the AMO request
457                         else begin
458                             uc_req_valid_o = 1'b1;
459                             st1_nop = 1'b1;
460 
461                             //  If the request comes from the replay table, free the
462                             //  corresponding RTAB entry
463                             st1_rtab_commit_o = st1_req_rtab_i;
464 
465                             if (cachedir_hit_i) begin
466                                 //  When the hit cacheline is dirty, flush its data to the memory
467                                 st2_flush_alloc_o = st1_dir_hit_dirty_i;
468 
469                                 //  Update the directory: an AMO request clears the dirty bit
470                                 //  because it triggers a flush of the cacheline before actually
471                                 //  executing the AMO.
472                                 //  An AMO does not set the dirty bit because it is always forwarded
473                                 //  to the memory. Then the local copy is updated with respect
474                                 //  to the old data from the memory.
475                                 st2_dir_updt_o = 1'b1;
476                                 st2_dir_updt_valid_o = 1'b1;
477                                 st2_dir_updt_wback_o = st1_dir_hit_wback_i;
478                                 st2_dir_updt_dirty_o = 1'b0;
479 
480                                 //  If the cacheline has been pre-allocated for a pending miss, keep
481                                 //  the fetch bit set
482                                 st2_dir_updt_fetch_o = st1_dir_hit_fetch_i;
483                             end
484 
485                             //  Performance event
486                             evt_uncached_req_o = 1'b1;
487                         end
488                     end
489                     //  }}}
490 
491                     //  Load cacheable request
492                     //  {{{
493                     if (|{st1_req_is_load_i,
494                           st1_req_is_cmo_prefetch_i})
495                     begin
496                         //  Cache miss
497                         //  {{{
498                         if (!cachedir_hit_i) begin
499                             //  A cache miss inserts a nop into the pipeline
500                             st1_nop = 1'b1;
501 
502                             //  If there is a match in the write buffer, send the entry right away
503                             wbuf_read_flush_hit_o = 1'b1;
504 
505                             //  Select a victim cacheline
506                             st1_req_cachedir_sel_victim_o = 1'b1;
507 
508                             //  Pending miss on the same line
509                             if (st1_mshr_hit_i) begin
510                                 st1_rtab_alloc = 1'b1;
511                                 st1_rtab_mshr_hit_o = 1'b1;
512                             end
513 
514                             //  No available slot in the MSHR
515                             else if (st1_mshr_full_i) begin
516                                 st1_rtab_alloc = 1'b1;
517                                 st1_rtab_mshr_full_o = 1'b1;
518                             end
519 
520                             //  All entries in the target set are being fetched
521                             else if (st1_dir_victim_unavailable_i) begin
522                                 st1_rtab_alloc = 1'b1;
523                                 st1_rtab_dir_unavailable_o = 1'b1;
524                             end
525 
526                             //  Hit on an open entry of the write buffer: wait for the entry to be
527                             //  acknowledged
528                             else if (wbuf_read_hit_i) begin
529                                 //  Put the request in the replay table
530                                 st1_rtab_alloc = 1'b1;
531                                 st1_rtab_wbuf_hit_o = 1'b1;
532                             end
533 
534                             //  Miss Handler is not ready to send
535                             else if (!st1_mshr_alloc_ready_i) begin
536                                 //  Put the request on hold if the MISS HANDLER is not
537                                 //  ready to send a new miss request. This is to prevent
538                                 //  a deadlock between the read request channel and the
539                                 //  read response channel.
540                                 //
541                                 //  The request channel may be stalled by targets if they
542                                 //  are not able to send a response (response is
543                                 //  prioritary). Therefore, we need to put the request on
544                                 //  hold to allow a possible refill read response to be
545                                 //  accomplished.
546                                 st1_rtab_alloc = 1'b1;
547                                 st1_rtab_mshr_ready_o = 1'b1;
548                             end
549 
550                             //  Flush pending on the miss cacheline
551                             else if (st1_flush_check_hit_i) begin
552                                 st1_rtab_alloc = 1'b1;
553                                 st1_rtab_flush_hit_o = 1'b1;
554                             end
555 
556                             //  Flush needed but the controller is not ready
557                             else if (st1_dir_victim_dirty_i && !st1_flush_alloc_ready_i) begin
558                                 st1_rtab_alloc = 1'b1;
559                                 st1_rtab_flush_not_ready_o = 1'b1;
560                             end
561 
562                             //  Forward the request to the next stage to allocate the
563                             //  entry in the MSHR and send the refill request
564                             else begin
565                                 //  When the victim cacheline is dirty, flush its data to the
566                                 //  memory
567                                 st2_flush_alloc_o = st1_dir_victim_dirty_i;
568 
569                                 //  If the request comes from the replay table, free the
570                                 //  corresponding RTAB entry
571                                 st1_rtab_commit_o = st1_req_rtab_i;
572 
573                                 //  Request a MSHR allocation
574                                 st2_mshr_alloc_o = 1'b1;
575                                 st2_mshr_alloc_need_rsp_o = st1_req_need_rsp_i;
576                                 st2_mshr_alloc_wback_o = (st1_req_wr_auto_i & cfg_default_wb_i) |
577                                                           st1_req_wr_wb_i;
578 
579                                 //  Update the cache directory state to FETCHING
580                                 st2_dir_updt_o = 1'b1;
581                                 st2_dir_updt_valid_o = st1_dir_victim_valid_i;
582                                 st2_dir_updt_wback_o = st1_dir_victim_wback_i;
583                                 st2_dir_updt_dirty_o = 1'b0;
584                                 st2_dir_updt_fetch_o = 1'b1;
585                             end
586                         end
587                         //  }}}
588 
589                         //  Cache hit
590                         //  {{{
591                         else begin
592                             //  Flush needed but the controller is not ready
593                             if (st1_req_wr_wt_i && st1_dir_hit_wback_i &&
594                                 st1_dir_hit_dirty_i && !st1_flush_alloc_ready_i)
595                             begin
596                                 st1_rtab_alloc = 1'b1;
597                                 st1_rtab_flush_not_ready_o = 1'b1;
598                                 st1_nop = 1'b1;
599                             end
600 
601                             //  Process the load
602                             else begin
603                                 //  If the request comes from the replay table, free the
604                                 //  corresponding RTAB entry
605                                 st1_rtab_commit_o = st1_req_rtab_i;
606 
607                                 //  Add a NOP when replaying a request, and there is no available
608                                 //  request from the replay table.
609                                 st1_nop = st1_req_rtab_i & ~rtab_req_valid_i;
610 
611                                 //  Update victim selection for the accessed set
612                                 st1_req_cachedir_updt_sel_victim_o = st1_req_is_load_i;
613 
614                                 //  Respond to the core (if needed)
615                                 st1_rsp_valid_o = st1_req_need_rsp_i;
616 
617                                 //  Performance event
618                                 evt_read_req_o = ~st1_req_is_cmo_prefetch_i;
619                                 evt_prefetch_req_o = st1_req_is_cmo_prefetch_i;
620 
621                                 //  If the cacheline is currently pre-allocated to be replaced, we
622                                 //  can only forward the data, but no state update is allowed.
623                                 if (!st1_dir_hit_fetch_i) begin
624                                     //  Hint is write-through but the current state is not. The
625                                     //  controller needs to update the state of the cacheline to WT
626                                     if (st1_req_wr_wt_i && st1_dir_hit_wback_i) begin
627                                         //  Update the directory state of the cacheline to WT
628                                         st2_dir_updt_o = 1'b1;
629                                         st2_dir_updt_valid_o = 1'b1;
630                                         st2_dir_updt_wback_o = 1'b0;
631                                         st2_dir_updt_dirty_o = 1'b0;
632                                         st2_dir_updt_fetch_o = 1'b0;
633 
634                                         //  Cacheline is dirty, flush its data to the memory
635                                         st2_flush_alloc_o = st1_dir_hit_dirty_i;
636 
637                                         st1_nop = 1'b1;
638                                     end
639 
640                                     //  Hint is write-back but the current state is not. The
641                                     //  controller needs to update the state of the cacheline to WB
642                                     //  (clean)
643                                     if (st1_req_wr_wb_i && !st1_dir_hit_wback_i) begin
644                                         //  Update the directory state of the cacheline to WB
645                                         st2_dir_updt_o = 1'b1;
646                                         st2_dir_updt_valid_o = 1'b1;
647                                         st2_dir_updt_wback_o = 1'b1;
648                                         st2_dir_updt_dirty_o = 1'b0;
649                                         st2_dir_updt_fetch_o = 1'b0;
650 
651                                         st1_nop = 1'b1;
652                                     end
653                                 end
654                             end
655                         end
656                         //  }}}
657                     end
658                     //  }}}
659 
660                     //  Store cacheable request
661                     //  {{{
662                     if (st1_req_is_store_i) begin
663                         //  Add a NOP in the pipeline when:
664                         //  - Structural hazard on the cache data if the st0 request is a load
665                         //    operation.
666                         //  - Replaying a request, the cache cannot accept a request from the
667                         //    core the next cycle. It can however accept a new request from the
668                         //    replay table
669                         //
670                         //  IMPORTANT: we could remove the NOP in the first scenario if the
671                         //  controller checks for the hit of this write. However, this adds
672                         //  a DIR_RAM -> DATA_RAM timing path.
673                         st1_nop = ((core_req_valid_i |  rtab_req_valid_i) & st0_req_is_load_i) |
674                                    (st1_req_rtab_i   & ~rtab_req_valid_i);
675 
676                         //  Enable the data RAM in case of write. However, the actual write
677                         //  depends on the hit signal from the cache directory.
678                         //
679                         //  IMPORTANT: this produces unnecessary power consumption in case of
680                         //  write misses, but removes timing paths between the cache directory
681                         //  RAM and the data RAM chip-select.
682                         st1_req_cachedata_write_o = 1'b1;
683 
684                         //  Pending miss on the same line
685                         if (st1_mshr_hit_i) begin
686                             //  Put the request in the replay table
687                             st1_rtab_alloc = 1'b1;
688                             st1_rtab_mshr_hit_o = 1'b1;
689 
690                             st1_nop = 1'b1;
691                         end
692 
693                         //  Hit in the flush controller
694                         else if (st1_flush_check_hit_i) begin
695                             //  Put the request in the replay table
696                             st1_rtab_alloc = 1'b1;
697                             st1_rtab_flush_hit_o = 1'b1;
698 
699                             st1_nop = 1'b1;
700                         end
701 
702                         //  Cache miss
703                         //  {{{
704                         else if (!cachedir_hit_i) begin
705                             //  Write is write-back
706                             //  {{{
707                             if (st1_req_wr_wb_i || (st1_req_wr_auto_i && cfg_default_wb_i))
708                             begin
709                                 //  Select a victim cacheline
710                                 st1_req_cachedir_sel_victim_o = 1'b1;
711 
712                                 //  If there is a match in the write buffer, send the entry right
713                                 //  away
714                                 wbuf_read_flush_hit_o = 1'b1;
715 
716                                 //  Add a nop as the next cycle the controller needs to write in the
717                                 //  MSHR and the directory
718                                 st1_nop = 1'b1;
719 
720                                 //  Miss Handler is not ready to send
721                                 if (!st1_mshr_alloc_ready_i) begin
722                                     st1_rtab_alloc = 1'b1;
723                                     st1_rtab_mshr_ready_o = 1'b1;
724                                 end
725 
726                                 //  No available slot in the MSHR
727                                 else if (st1_mshr_full_i) begin
728                                     //  Put the request in the replay table
729                                     st1_rtab_alloc = 1'b1;
730                                     st1_rtab_mshr_full_o = 1'b1;
731                                 end
732 
733                                 //  Hit on an entry of the write buffer: wait for the entry to be
734                                 //  acknowledged
735                                 else if (wbuf_read_hit_i) begin
736                                     //  Put the request in the replay table
737                                     st1_rtab_alloc = 1'b1;
738                                     st1_rtab_wbuf_hit_o = 1'b1;
739                                 end
740 
741                                 //  no available victim cacheline (all currently pre-allocated and
742                                 //  waiting to be refilled)
743                                 else if (st1_dir_victim_unavailable_i) begin
744                                     //  Put the request in the replay table
745                                     st1_rtab_alloc = 1'b1;
746                                     st1_rtab_dir_unavailable_o = 1'b1;
747                                 end
748 
749                                 //  Flush needed but the controller is not ready
750                                 else if (st1_dir_victim_dirty_i && !st1_flush_alloc_ready_i) begin
751                                     st1_rtab_alloc = 1'b1;
752                                     st1_rtab_flush_not_ready_o = 1'b1;
753                                 end
754 
755                                 else begin
756                                     //  When the victim cacheline is dirty, flush its data to the
757                                     //  memory
758                                     st2_flush_alloc_o = st1_dir_victim_dirty_i;
759 
760                                     //  Update the directory state of the cacheline to FETCHING
761                                     st2_dir_updt_o = 1'b1;
762                                     st2_dir_updt_valid_o = st1_dir_victim_valid_i;
763                                     st2_dir_updt_wback_o = st1_dir_victim_wback_i;
764                                     st2_dir_updt_dirty_o = 1'b0;
765                                     st2_dir_updt_fetch_o = 1'b1;
766 
767                                     //  Send a miss request to the memory (write-allocate)
768                                     st2_mshr_alloc_o = 1'b1;
769                                     st2_mshr_alloc_need_rsp_o = 1'b0;
770                                     st2_mshr_alloc_wback_o = 1'b1;
771                                     // FIXME Optimization: ask here the miss handler to set the
772                                     //       dirty bit when the new cacheline is refilled to avoid
773                                     //       the update penalty of the pending write
774                                     // st2_mshr_alloc_dirty_o = 1'b1
775 
776                                     //  Put the request in the replay table
777                                     st1_rtab_alloc = 1'b1;
778                                     st1_rtab_write_miss_o = 1'b1;
779 
780                                     //  Performance event
781                                     evt_cache_write_miss_o = 1'b1;
782                                 end
783                             end
784                             //  }}}
785 
786                             //  Write is write-through
787                             //  {{{
788                             else begin
789                                 //  Request write into the write-buffer
790                                 wbuf_write_valid_o = 1'b1;
791 
792                                 //  No available entry in the write buffer (or conflict on pending
793                                 //  entry)
794                                 if (!wbuf_write_ready_i) begin
795                                     //  Put the request in the replay table
796                                     st1_rtab_alloc = 1'b1;
797                                     st1_rtab_wbuf_not_ready_o = 1'b1;
798 
799                                     st1_nop = 1'b1;
800                                 end
801 
802                                 else begin
803                                     //  If the request comes from the replay table, free the
804                                     //  corresponding RTAB entry
805                                     st1_rtab_commit_o = st1_req_rtab_i;
806 
807                                     //  Respond to the core (if needed)
808                                     st1_rsp_valid_o = st1_req_need_rsp_i;
809 
810                                     //  Performance event
811                                     evt_cache_write_miss_o = 1'b1;
812                                     evt_write_req_o        = 1'b1;
813                                 end
814                             end
815                             //  }}}
816                         end
817                         //  }}}
818 
819                         //  Cache hit
820                         //  {{{
821                         else begin
822                             //  The target cacheline is pre-allocated to be replaced. Put this write
823                             //  on-hold
824                             if (st1_dir_hit_fetch_i) begin
825                                 //  Put the request in the replay table
826                                 st1_rtab_alloc = 1'b1;
827                                 st1_rtab_dir_fetch_o = 1'b1;
828 
829                                 st1_nop = 1'b1;
830                             end
831 
832                             //  Write is write-back
833                             //  {{{
834                             else if (st1_req_wr_wb_i || (st1_req_wr_auto_i && st1_dir_hit_wback_i))
835                             begin
836                                 //  If there is a match in the write buffer, send the entry right
837                                 //  away
838                                 wbuf_read_flush_hit_o = 1'b1;
839 
840                                 //  Hit on an entry of the write buffer: wait for the entry to be
841                                 //  acknowledged.
842                                 //
843                                 //  This check is to avoid a possible future race when flushing
844                                 //  a dirty cacheline if there is a pending write in the write
845                                 //  buffer concerning the same cacheline
846                                 if (wbuf_read_hit_i) begin
847                                     //  Put the request in the replay table
848                                     st1_rtab_alloc = 1'b1;
849                                     st1_rtab_wbuf_hit_o = 1'b1;
850                                     st1_nop = 1'b1;
851 
852                                 end else begin
853                                     // Update the directory state of the cacheline to dirty
854                                     if (!st1_dir_hit_wback_i || !st1_dir_hit_dirty_i) begin
855                                         st2_dir_updt_o       = 1'b1;
856                                         st2_dir_updt_valid_o = 1'b1;
857                                         st2_dir_updt_wback_o = 1'b1;
858                                         st2_dir_updt_dirty_o = 1'b1;
859                                         st2_dir_updt_fetch_o = 1'b0;
860 
861                                         st1_nop = 1'b1;
862                                     end
863 
864                                     //  If the request comes from the replay table, free the
865                                     //  corresponding RTAB entry
866                                     st1_rtab_commit_o = st1_req_rtab_i;
867 
868                                     //  Respond to the core
869                                     st1_rsp_valid_o = st1_req_need_rsp_i;
870 
871                                     //  Write in the data RAM
872                                     st1_req_cachedata_write_enable_o = 1'b1;
873 
874                                     //  Update victim selection for the accessed set
875                                     st1_req_cachedir_updt_sel_victim_o = 1'b1;
876 
877                                     //  Performance event
878                                     evt_write_req_o = 1'b1;
879                                 end
880                             end
881                             //  }}}
882 
883                             //  Write is write-through
884                             //  {{{
885                             else begin
886                                 //  Write in the write buffer unless we need to flush the cacheline
887                                 //  first
888                                 wbuf_write_valid_o = ~st1_dir_hit_dirty_i;
889 
890                                 //  The cache needs to flush the cacheline but the flush controller
891                                 //  is not ready
892                                 if (st1_dir_hit_dirty_i && !st1_flush_alloc_ready_i) begin
893                                     st1_rtab_alloc = 1'b1;
894                                     st1_rtab_flush_not_ready_o = 1'b1;
895 
896                                     st1_nop = 1'b1;
897                                 end
898 
899                                 //  Flush the cacheline but keep it in the cache
900                                 else if (st1_dir_hit_dirty_i) begin
901                                     //  Flush cacheline data to the memory
902                                     st2_flush_alloc_o = 1'b1;
903 
904                                     //  Update the state to WT in the directory
905                                     st2_dir_updt_o = 1'b1;
906                                     st2_dir_updt_valid_o = 1'b1;
907                                     st2_dir_updt_wback_o = 1'b0;
908                                     st2_dir_updt_dirty_o = 1'b0;
909                                     st2_dir_updt_fetch_o = 1'b0;
910 
911                                     //  Put the request in the replay table while waiting for the
912                                     //  memory flushing
913                                     st1_rtab_alloc = 1'b1;
914                                     st1_rtab_flush_hit_o = 1'b1;
915 
916                                     st1_nop = 1'b1;
917                                 end
918 
919                                 //  No available entry in the write buffer (or conflict on pending
920                                 //  entry)
921                                 else if (!wbuf_write_ready_i) begin
922                                     //  Put the request in the replay table
923                                     st1_rtab_alloc = 1'b1;
924                                     st1_rtab_wbuf_not_ready_o = 1'b1;
925 
926                                     st1_nop = 1'b1;
927                                 end
928 
929                                 //  The store can be performed in the write buffer and in the cache
930                                 else begin
931                                     //  If the request comes from the replay table, free the
932                                     //  corresponding RTAB entry
933                                     st1_rtab_commit_o = st1_req_rtab_i;
934 
935                                     //  Respond to the core
936                                     st1_rsp_valid_o = st1_req_need_rsp_i;
937 
938                                     //  Update victim selection for the accessed set
939                                     st1_req_cachedir_updt_sel_victim_o = 1'b1;
940 
941                                     //  Write in the data RAM
942                                     st1_req_cachedata_write_enable_o = 1'b1;
943 
944                                     //  Performance event
945                                     evt_write_req_o = 1'b1;
946                                 end
947                             end
948                             //  }}}
949                         end
950                         //  }}}
951                     end
952                     //  }}}
953                 end
954                 // }}}
955             end
956             //  }}}
957 
958             //  New request
959             //  {{{
960             nop = st1_nop | st2_nop;
961 
962             //     New requests/refill are served according to the following priority:
963             //     0 - Refills/Invalidations (Highest priority)
964             //     1 - Replay Table
965             //     2 - Core (Lowest priority)
966 
967             //     * IMPORTANT: When the replay table is full, the cache
968             //       cannot accept new core requests to prevent a deadlock: If
969             //       the core request needs to be put on hold, as there is no
970             //       place the replay table, the pipeline needs to stall. If
971             //       the pipeline is stalled, dependencies of on-hold requests
972             //       cannot be solved, creating a deadlock
973             core_req_ready_o = core_req_valid_i
974                                & ~rtab_req_valid_i
975                                & ~refill_req_valid_i
976                                & ~rtab_full_i
977                                & ~cmo_busy_i
978                                & ~uc_busy_i
979                                & ~rtab_fence_i
980                                & ~nop;
981 
982             rtab_req_ready_o = rtab_req_valid_i
983                                & ~refill_req_valid_i
984                                & (~cmo_busy_i | cmo_wait_i)
985                                & ~nop;
986 
987             refill_req_ready_o = refill_req_valid_i
988                                  & (~cmo_busy_i | cmo_wait_i)
989                                  & ~st1_req_valid_i
990                                  & ~(st2_mshr_alloc_i | st2_dir_updt_i);
991 
992             //      Forward the core/rtab request to stage 1
993             st1_req_valid_o = core_req_ready_o | rtab_req_ready_o;
994             st1_req_is_error_o = st0_req_is_error_i;
995 
996             //      New cacheable stage 0 request granted
997             //      {{{
998             //          IMPORTANT: here the RAM is enabled independently if the
999             //          request needs to be put on-hold.
1000             //          This increases the power consumption in that cases, but
1001             //          removes the timing paths RAM-to-RAM between the cache
1002             //          directory and the data array.
1003             if ((core_req_ready_o | rtab_req_ready_o) &&
1004                 !st0_req_is_uncacheable_i &&
1005                 !st0_req_is_error_i)
1006             begin
1007                 st1_req_is_cacheable_store = st1_req_valid_i & st1_req_is_store_i &
1008                         ~st1_req_is_uncacheable_i;
1009 
1010                 st0_req_cachedata_read_o = st0_req_is_load_i &
1011                         (~st1_req_is_cacheable_store | st1_req_is_error_i);
1012 
1013                 if (st0_req_is_load_i         |
1014                     st0_req_is_cmo_prefetch_i |
1015                     st0_req_is_store_i        |
1016                     st0_req_is_amo_i          )
1017                 begin
1018                     st0_req_mshr_check_o    = 1'b1;
1019                     st0_req_cachedir_read_o = 1'b1;
1020                 end
1021             end
1022             //      }}}
1023             //  }}}
1024         end
1025         //  }}} end of normal pipeline operation
1026     end
1027     //  }}}
1028 endmodule
